import {announce} from '@github-ui/aria-live'
import {SortAscIcon, SortDescIcon} from '@primer/octicons-react'
import {Button} from '@primer/styled-react'
import {type PropsWithChildren, useCallback, useMemo} from 'react'

import styles from './SortHeader.module.css'

export type SortDirection = 'asc' | 'desc'

export type Sort<Row> = {
  field: keyof Row
  direction: SortDirection
}

interface SortHeaderProps<Row> {
  field: keyof Row
  sort: Sort<Row>
  onSortChange: (sort: Sort<Row>) => void
}

const DEFAULT_SORT_DIRECTION: SortDirection = 'desc'

const getDirectionText = (direction: SortDirection): string => (direction === 'asc' ? 'ascending' : 'descending')
const getOppositeDirection = (direction: SortDirection): SortDirection => (direction === 'asc' ? 'desc' : 'asc')

export default function SortHeader<Row = unknown>({
  field,
  sort,
  onSortChange,
  children,
}: PropsWithChildren<SortHeaderProps<Row>>): React.ReactElement {
  // Extract column name logic
  const columnName = useMemo(() => {
    return typeof children === 'string' ? children : 'column'
  }, [children])

  // Determine if this column is currently sorted
  const isCurrentlySorted = sort.field === field

  // Calculate next sort direction
  const getNextSortDirection = useCallback((): SortDirection => {
    if (!isCurrentlySorted) return DEFAULT_SORT_DIRECTION
    return getOppositeDirection(sort.direction)
  }, [isCurrentlySorted, sort.direction])

  // Handle sort action
  const handleSortAction = useCallback(() => {
    const newDirection = getNextSortDirection()
    onSortChange({field, direction: newDirection})

    // Announce the change for screen readers
    announce(`${columnName} sorted ${getDirectionText(newDirection)}`)
  }, [field, getNextSortDirection, onSortChange, columnName])

  const sortIcon = useMemo(() => {
    if (!isCurrentlySorted) return null

    const IconComponent = sort.direction === 'asc' ? SortAscIcon : SortDescIcon
    const testId = sort.direction === 'asc' ? 'sort-icon-asc' : 'sort-icon-desc'

    return (
      <div data-testid={testId}>
        <IconComponent />
      </div>
    )
  }, [isCurrentlySorted, sort.direction])

  const ariaLabel = useMemo(() => {
    if (isCurrentlySorted) {
      const currentDirection = getDirectionText(sort.direction)
      const nextDirection = getDirectionText(getOppositeDirection(sort.direction))
      return `${columnName}, sorted ${currentDirection}. Click to sort ${nextDirection}.`
    }
    return `${columnName}, not sorted. Click to sort ${getDirectionText(DEFAULT_SORT_DIRECTION)}.`
  }, [isCurrentlySorted, sort.direction, columnName])

  return (
    <Button
      data-testid="sort-button"
      variant="invisible"
      onClick={handleSortAction}
      aria-label={ariaLabel}
      sx={{
        // If we're sorted by this field, use Button's default color (darker)
        // Otherwise, inherit Table's color
        color: isCurrentlySorted ? undefined : 'inherit',
      }}
      className={styles.Button}
    >
      <div className={styles.Box}>
        {sortIcon}
        {children}
      </div>
    </Button>
  )
}

try{ SortHeader.displayName ||= 'SortHeader' } catch {}