import type {UseQueryResult} from '@github-ui/react-query'

import {usePaths} from '../../../common/contexts/Paths'
import {useQuery} from '../../../common/hooks/use-config-query'
import {fetchJson} from '../../../common/utils/fetch-json'

export type AlertTrendsResult = {
  label: string
  points: Array<{
    x: string
    y: number
  }>
}

interface UseAlertTrendsQueryParams {
  query: string
  // Although funnelOrder is always calculated by `AlertsFunnelCard`, we intentionally left it as optional so that
  // we don't have to spell it out in every unit test.
  // This shouldn't bite us because the Rails controller endpoint treats it as an optional param.
  funnelOrder?: string
}

export default function useAlertTrendsQuery({
  query,
  funnelOrder,
}: UseAlertTrendsQueryParams): UseQueryResult<AlertTrendsResult> {
  const paths = usePaths()
  const path = paths.dependabotAlertTrendsPath({
    query,
    funnelOrder,
  })

  return useQuery({
    queryKey: [path],
    queryFn: () => fetchJson(path),
  })
}
